public bool IsValidReplace(string s)
{
    string previous;

    do
    {
        previous = s;
        s = s.Replace("()", string.Empty)
             .Replace("[]", string.Empty)
             .Replace("{}", string.Empty);
    }
    while (s != previous);

    return s.Length == 0;
}

public bool IsValid(string s)
{
    var stack = new Stack<char>();

    foreach (char c in s)
    {
        if (c is '(' or '[' or '{')
        {
            stack.Push(c);
        }
        else
        {
            // A closing bracket with nothing to match is invalid
            if (stack.Count == 0) return false;

            char open = stack.Pop();

            bool matches = (c == ')' && open == '(')
                        || (c == ']' && open == '[')
                        || (c == '}' && open == '{');

            if (!matches) return false;
        }
    }

    // Every opening bracket must have been closed
    return stack.Count == 0;
}

public bool CheckValidString(string s)
{
    int low = 0;    // fewest open brackets possible
    int high = 0;   // most open brackets possible

    foreach (char c in s)
    {
        if (c == '(') { low++; high++; }
        else if (c == ')') { low = Math.Max(low - 1, 0); high--; }
        else { low = Math.Max(low - 1, 0); high++; } // '*' could be either

        // More closes than possible opens
        if (high < 0) return false;
    }

    // The balance can reach zero exactly when low is zero
    return low == 0;
}

public bool IsValid(string s)
{
    var expected = new Stack<char>();

    foreach (char c in s)
    {
        switch (c)
        {
            case '(': expected.Push(')'); break;
            case '[': expected.Push(']'); break;
            case '{': expected.Push('}'); break;
            default:
                if (expected.Count == 0 || expected.Pop() != c) return false;
                break;
        }
    }

    return expected.Count == 0;
}
